head.script:
scwin.onpageload = function() {
    $p.executeSubmission("submission1");
};
scwin.onpageunload = function() {};
scwin.anchor1_onclick = function() {
    /* 엑셀 다운로드 시 colMerge, mergeCell 동시 사용 시 mergeCell 적용 안됨. */
    var nowDate = new Date();
    var options = {
        fileName: "EQ Trend Report_t.xls"
            //, useSubTotal : true	//엑셀에 subtotal 적용, total은 기본세팅되어있음
            ,
        colMerge: true,
        mergeCell: true
    };
    gvListTab1.advancedExcelDownload(options);
};
scwin.callBack = function(e) {
    debugger;
    dlTab1List.setJSON(JSON.parse(e.responseText).dlTab1List);
    var mergeInfo = {
        rowIndex: 0,
        colIndex: 0,
        rowSpan: 8,
        colSpan: 10
    };
    gvListTab1.mergeCell(mergeInfo);
};
